document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#search').oninput=()=>{state.limit=60;render();};$('#sort').onchange=()=>render();$('#market').onchange=e=>{state.market=e.target.value;state.itemFilters={};load();};$('#periods').onclick=e=>{const b=e.target.closest('[data-days]');if(!b)return;state.days=Number(b.dataset.days);document.querySelectorAll('[data-days]').forEach(x=>x.classList.toggle('active',x===b));load();};$('#refresh').onclick=load;$('#close-detail').onclick=()=>$('#detail').close();$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>8*1024*1024)throw Error('Import must be smaller than 8 MiB');const data=JSON.parse(await f.text());await api(state.data?.hosted?'characters/import':'import',data.events?data:{events:[data]});await load();}catch(err){error(err);}finally{e.target.value='';}};load();setInterval(async()=>{if(document.visibilityState==='hidden')return;try{if(!state.data){await load();return;}const info=await api('status');state.data.capture=info.capture;captureStatus();if(!state.loading&&info.revision!==state.data.revision&&state.view!=='settings'&&!$('#detail').open&&!document.querySelector('#content input:focus, #content select:focus'))await load();}catch(err){$('#connection').textContent='Connection unavailable';$('.connection').classList.add('off');}},5000);

$('#scan-help').onclick=()=>{const body=$('#detail-body');body.replaceChildren(el('h2','','Update market data'));const steps=el('ol','next-steps');for(const text of ['At an auction house in WoW, open LamdaMarket and choose Scan auctions.','The game first gathers the catalog. Then the capture panel shows a sending percentage and estimated time remaining. Keep the colored transfer area uncovered.','The browser confirms received pages. If a catalog is incomplete, choose Resend export in WoW.','Open an item’s auction results to capture actual stack prices. Use Copy AH search in an item’s details, then paste the name into WoW.','Open each profession to export known recipes. Merchant visits add observed vendor offers.'])steps.append(el('li','',text));if(state.data.hosted){body.append(el('p','muted','This site receives observations from approved Lamda Engine collectors. You can use the shared prices without running a collector.'));}else body.append(steps);$('#detail').showModal();};

$('#item-class').onchange=e=>{const f=itemFilters();f.classID=e.target.value;f.subclassID='';state.limit=60;render();};
$('#item-subclass').onchange=e=>{itemFilters().subclassID=e.target.value;state.limit=60;render();};
$('#clear-item-filters').onclick=clearItemFilters;

$('#favorite-list').onchange=e=>{state.activeListID=e.target.value;delete state.itemFilters.watchlist;$('#search').value='';state.listSort='manual';$('#sort').value='manual';state.limit=60;render();};
$('#new-list').onclick=()=>listEditor();$('#rename-list').onclick=()=>listEditor(currentList());
$('#delete-list').onclick=async()=>{const l=currentList();if(l.default||!confirm('Delete “'+l.name+'”? Item prices and other lists will be kept.'))return;try{await api('lists/delete',{id:l.id});state.activeListID='favorites';await load();}catch(err){error(err);}};
$('#find-list-items').onclick=()=>navigate('market','');
$('#add-results-to-list').onclick=()=>listPicker(itemCandidates().filter(c=>matchesItemFilters(c)&&(c.name+' '+c.id).toLowerCase().includes($('#search').value.toLowerCase())).map(c=>c.id));

async function exportCharacters(){try{const data=await api('characters/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='lamda-characters.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){error(err);}}
async function sharingSettings(parent){
 const panel=el('section','panel sharing-panel');panel.append(el('h2','','Shared market'));parent.append(panel);
 if(state.data.hosted){try{const account=await api('account');panel.append(el('p','',account.email),el('p','muted','Auction observations are shared. Your lists, characters, holdings and research settings belong to your account.'));const logout=el('a','','Sign out');logout.href='/cdn-cgi/access/logout';panel.append(logout);if(account.owner)panel.append(action('Manage collectors',collectorManager));}catch(err){panel.append(el('p','form-message',err.message));}return;}
 try{const status=await api('publisher');const form=el('form','list-form'),label=el('label','','Shared site address'),url=el('input');url.type='url';url.placeholder='https://market.lamdaui.com';url.value=status.url;label.append(url);const enabledLabel=el('label','checkline'),enabled=el('input');enabled.type='checkbox';enabled.checked=status.enabled;enabledLabel.append(enabled,'Send auction observations');const key=el('input');key.value=status.publicKey;key.readOnly=true;key.setAttribute('aria-label','Collector public key');const keyLabel=el('label','','Collector public key');keyLabel.append(key);panel.append(el('p','muted','Authorize this public key in the shared site’s collector settings. Only auction prices, item information, vendor offers and recipe definitions are sent. Character exports and your lists stay here.'));const save=el('button','','Save sharing settings');save.type='submit';const message=el('p','save-status');message.textContent=status.error||(status.enabled?status.pending+' observations waiting · last sync '+(status.lastSync?age(status.lastSync):'never'):'Sharing is off');form.append(label,enabledLabel,keyLabel,save,message);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('publisher',{url:url.value,enabled:enabled.checked});message.textContent='Sharing settings saved';}catch(err){message.textContent=err.message;}finally{save.disabled=false;}};panel.append(form);}catch(err){panel.append(el('p','muted',err.message));}
}
async function collectorManager(){
 try{const list=await api('collectors'),body=$('#detail-body');body.replaceChildren(el('h2','','Collectors'),el('p','muted','Approved collectors can contribute shared auction observations. Character exports use a separate import.'));
 for(const c of list){const row=el('div','collector-row');row.append(el('strong','',c.name),el('small','muted',c.lastSeen?'Last upload '+age(c.lastSeen):'No uploads yet'),action(c.enabled?'Disable':'Enable',async()=>{try{await api('collectors',{name:c.name,publicKey:c.publicKey,enabled:!c.enabled});collectorManager();}catch(err){error(err);}}));body.append(row);}
 const form=el('form','list-form'),name=el('input'),key=el('input');name.required=true;name.maxLength=80;name.placeholder='Home PC';key.required=true;key.placeholder='Paste the public key from Lamda Engine';for(const [title,input]of [['Collector name',name],['Public key',key]]){const label=el('label','',title);label.append(input);form.append(label);}const save=el('button','','Authorize collector');save.type='submit';const message=el('p','form-message');form.append(save,message);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('collectors',{name:name.value,publicKey:key.value.trim(),enabled:true});collectorManager();}catch(err){message.textContent=err.message;}finally{save.disabled=false;}};body.append(form);if(!$('#detail').open)$('#detail').showModal();}catch(err){error(err);}
}
